solution:
package main

import "fmt"

func Sum(xs []int) int {
	total := 0
	for _, x := range xs {
		total += x
	}
	return total
}

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))
}

alt:
package main

import "fmt"

func Sum(xs []int) int {
	total := 0
	for i := 0; i < len(xs); i++ {
		total += xs[i]
	}
	return total
}

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))
}
